using System;using System.IO;using System.Drawing;using System.Reflection;using System.Diagnostics;using System.Threading.Tasks;using System.Windows.Forms;using Microsoft.Win32;using System.IO.Compression;
class PriintSetup {
 static readonly string AppRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Priint");
 const string UninstallKey=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\Priint";
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();try{
  if(args.Length>=2&&args[0]=="--test-install"){Install(args[1],false);return;}
  if(args.Length>=2&&args[0]=="--test-remove"){Remove(args[1],false);return;}
  if(args.Length>0&&args[0]=="--silent"){Install(AppRoot,true);return;}
  if(args.Length>0&&args[0]=="--uninstall"){if(MessageBox.Show("Desinstalar o Priint? Seus vídeos, prints e preferências serão preservados.","Priint",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;string temp=Path.Combine(Path.GetTempPath(),"Priint-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Application.ExecutablePath,temp);Process.Start(new ProcessStartInfo(temp,"--remove \""+AppRoot+"\" "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true});return;}
  if(args.Length>=3&&args[0]=="--remove"){try{Process.GetProcessById(int.Parse(args[2])).WaitForExit(5000);}catch{}if(Path.GetFullPath(args[1])!=Path.GetFullPath(AppRoot))throw new Exception("Pasta de desinstalação inválida.");Remove(AppRoot,true);MessageBox.Show("Priint desinstalado. Seus arquivos e preferências foram preservados.","Priint");return;}
  Application.Run(new SetupForm());
 }catch(Exception ex){if(args.Length>0){File.WriteAllText(Path.Combine(Path.GetTempPath(),"Priint-setup-error.txt"),ex.ToString());Environment.ExitCode=1;}else MessageBox.Show(ex.Message,"Priint · Instalação",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 static string Encoder(){foreach(var part in (Environment.GetEnvironmentVariable("PATH")??"").Split(';')){try{string path=Path.Combine(part.Trim('"'),"ffmpeg.exe");if(File.Exists(path)&&File.Exists(Path.Combine(Path.GetDirectoryName(path),"ffprobe.exe")))return path;}catch{}}string packages=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Microsoft","WinGet","Packages");if(Directory.Exists(packages))foreach(var root in Directory.GetDirectories(packages,"Gyan.FFmpeg_*"))foreach(var version in Directory.GetDirectories(root)){string path=Path.Combine(version,"bin","ffmpeg.exe");if(File.Exists(path)&&File.Exists(Path.Combine(version,"bin","ffprobe.exe")))return path;}string installed=Path.Combine(AppRoot,"tools","ffmpeg.exe");return File.Exists(installed)?installed:null;}
 static void CheckClosed(string root){foreach(var p in Process.GetProcessesByName("Priint")){using(p){try{if(string.Equals(p.MainModule.FileName,Path.Combine(root,"Priint.exe"),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Feche o Priint pelo menu da bandeja antes de continuar.");}catch(InvalidOperationException){throw;}catch{}}}}
 static void Commit(string staged,string target){if(File.Exists(target))File.Replace(staged,target,null);else File.Move(staged,target);}
 static void Install(string root,bool integrate){root=Path.GetFullPath(root);CheckClosed(root);Directory.CreateDirectory(root);string tools=Path.Combine(root,"tools");Directory.CreateDirectory(tools);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Priint.app"))using(var file=File.Create(Path.Combine(root,"Priint.exe.new")))stream.CopyTo(file);
 using(var bundle=Assembly.GetExecutingAssembly().GetManifestResourceStream("Priint.tools"))using(var zip=new ZipArchive(bundle,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){string name=entry.FullName;if(name!="ffmpeg.exe"&&name!="ffprobe.exe"&&name!="FFMPEG-LICENSE.txt")throw new Exception("Componente de gravação inválido.");string target=Path.Combine(tools,name);using(var input=entry.Open())using(var destination=File.Create(target+".new"))input.CopyTo(destination);Commit(target+".new",target);}}
 using(var bundle=Assembly.GetExecutingAssembly().GetManifestResourceStream("Priint.dependencies"))using(var zip=new ZipArchive(bundle,ZipArchiveMode.Read)){var manifest=new System.Collections.Generic.List<string>();foreach(var entry in zip.Entries){string name=entry.FullName;if(name!=Path.GetFileName(name)||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new Exception("Dependência inválida.");string output=Path.Combine(root,name);using(var input=entry.Open())using(var destination=File.Create(output+".new"))input.CopyTo(destination);Commit(output+".new",output);manifest.Add(name);}File.WriteAllLines(Path.Combine(root,".priint-deps.txt"),manifest.ToArray());} Commit(Path.Combine(root,"Priint.exe.new"),Path.Combine(root,"Priint.exe"));string uninstall=Path.Combine(root,"Uninstall.exe");if(!string.Equals(Application.ExecutablePath,uninstall,StringComparison.OrdinalIgnoreCase)){File.Copy(Application.ExecutablePath,uninstall+".new",true);Commit(uninstall+".new",uninstall);}File.WriteAllText(Path.Combine(root,".priint-install"),"Priint.Install.v1");
 File.WriteAllText(Path.Combine(root,"LEIA-ME.txt"),"Priint 6.0.1\r\nClique esquerdo na bandeja ou atalho: print.\r\nMenu direito: Gravar tela, Opções, Sobre e Sair.\r\nCtrl+Shift+F9: Studio/parar gravação.\r\nOpções: Geral, Atalhos, Print e Gravação. Permissões de câmera/microfone: Configurações de gravação > Acesso.\r\nFPS:30,60,120,240 (seletor). Taxa alvo depende da configuração. CPU ou GPU NVIDIA identificada. MP4/H.264/H.265; AVI/H.264. Resolução, qualidade, bitrate e MP3 separado em Configurações de gravação. Áudio do computador e/ou microfone configurável. Câmera apenas monitor/janela/desktop. Janela é visível: sobreposições aparecem.\r\nFFmpeg/ffprobe acompanham este instalador.\r\nhttps://ffmpeg.org/legal.html\r\nPreferências e gravações são preservadas ao desinstalar.");
 if(integrate){string programs=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Priint");Directory.CreateDirectory(programs);Shortcut(Path.Combine(programs,"Priint.lnk"),Path.Combine(root,"Priint.exe"),"--background");Shortcut(Path.Combine(programs,"Priint Studio.lnk"),Path.Combine(root,"Priint.exe"),"--studio");Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Priint.lnk"),Path.Combine(root,"Priint.exe"),"--studio");using(var key=Registry.CurrentUser.CreateSubKey(UninstallKey)){key.SetValue("DisplayName","Priint");key.SetValue("DisplayVersion","6.0.1");key.SetValue("Publisher","Dobs by Azura");key.SetValue("InstallLocation",root);key.SetValue("DisplayIcon",Path.Combine(root,"Priint.exe"));key.SetValue("UninstallString","\""+uninstall+"\" --uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}using(var run=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){if(run!=null&&run.GetValue("Priint")!=null)run.SetValue("Priint","\""+Path.Combine(root,"Priint.exe")+"\" --background");}}
 }
 static void Shortcut(string path,string target,string args){object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object link=null;try{link=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path});link.GetType().InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{target});link.GetType().InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{args});link.GetType().InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{Path.GetDirectoryName(target)});link.GetType().InvokeMember("IconLocation",BindingFlags.SetProperty,null,link,new object[]{target+",0"});link.GetType().InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}finally{if(link!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
 static void Remove(string root,bool integrate){root=Path.GetFullPath(root);string marker=Path.Combine(root,".priint-install");if(!File.Exists(marker)||File.ReadAllText(marker)!="Priint.Install.v1")throw new Exception("A pasta não contém uma instalação Priint reconhecida.");CheckClosed(root);string manifestPath=Path.Combine(root,".priint-deps.txt");if(File.Exists(manifestPath)){foreach(string name in File.ReadAllLines(manifestPath)){if(name==Path.GetFileName(name)&&name.IndexOfAny(Path.GetInvalidFileNameChars())<0){string dependency=Path.Combine(root,name);if(File.Exists(dependency))File.Delete(dependency);}}File.Delete(manifestPath);}foreach(string file in new[]{"Priint.exe","Uninstall.exe","LEIA-ME.txt",".priint-install","tools\\ffmpeg.exe","tools\\ffprobe.exe","tools\\FFMPEG-LICENSE.txt"}){string path=Path.Combine(root,file);if(File.Exists(path))File.Delete(path);}try{Directory.Delete(Path.Combine(root,"tools"),false);}catch{}try{Directory.Delete(root,false);}catch{}
 if(integrate){string programs=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Priint");foreach(string file in new[]{Path.Combine(programs,"Priint.lnk"),Path.Combine(programs,"Priint Studio.lnk"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Priint.lnk")})if(File.Exists(file))File.Delete(file);try{Directory.Delete(programs,false);}catch{}Registry.CurrentUser.DeleteSubKey(UninstallKey,false);using(var run=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){string command=run==null?null:run.GetValue("Priint") as string;if(command!=null&&command.IndexOf(Path.Combine(root,"Priint.exe"),StringComparison.OrdinalIgnoreCase)>=0)run.DeleteValue("Priint",false);}}
 }
 class SetupForm:Form {public SetupForm(){Text="Instalar Priint 6.0.1";ClientSize=new Size(560,340);BackColor=Color.FromArgb(21,24,26);ForeColor=Color.White;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("Priint.ico"))Icon=new Icon(s);Controls.Add(new Label{Text="priint.",ForeColor=Color.FromArgb(118,185,0),Font=new Font("Segoe UI",32,FontStyle.Bold),AutoSize=true,Location=new Point(28,18)});Controls.Add(new Label{Text="Prints e gravações, sempre à mão.",AutoSize=true,Location=new Point(32,90)});Controls.Add(new Label{Text="Instalação para seu usuário, sem administrador.\nCria atalhos no menu Iniciar e na área de trabalho.\nInclui os componentes de gravação FFmpeg.\nSeus prints, vídeos e preferências serão preservados.",AutoSize=true,Location=new Point(32,135)});var status=new Label{Location=new Point(32,230),Size=new Size(495,48)};Controls.Add(status);var install=new Button{Text="Instalar Priint",BackColor=Color.FromArgb(118,185,0),ForeColor=Color.Black,FlatStyle=FlatStyle.Flat,Location=new Point(355,284),Size=new Size(171,36)};Controls.Add(install);bool completed=false;bool working=false;FormClosing+=delegate(object sender,FormClosingEventArgs e){if(working)e.Cancel=true;};install.Click+=async delegate{if(completed){Close();return;}working=true;install.Enabled=false;ControlBox=false;status.Text="Instalando aplicativo e componentes de gravação…";try{await Task.Run(()=>Install(AppRoot,true));status.Text="Priint instalado. Os atalhos já estão disponíveis.";install.Text="Concluir";completed=true;}catch(Exception ex){status.Text=ex.Message;install.Text="Tentar novamente";}finally{working=false;install.Enabled=true;ControlBox=true;}};}}
}




